  const oldMenu=renderMenu;renderMenu=function(t){return oldMenu(t).replace('<button class="danger-action"',`<button role="menuitem" data-recovery26="open">${icon('folder')}最近删除</button><button class="danger-action"`);};
  const oldNoteMenu=showKnowledgeFileMenu;showKnowledgeFileMenu=function(trigger){oldNoteMenu(trigger);if(currentTask()?.notes?.trim())$('#overlay [role="menu"]')?.insertAdjacentHTML('beforeend',`<div class="menu-divider"></div><button role="menuitem" class="button danger-action" data-recovery26="delete-note">${icon('close')}移除软件内笔记…</button>`);};
  function bridge(){document.querySelectorAll('[data-bulk-action="delete"]').forEach(b=>{delete b.dataset.bulkAction;b.dataset.recovery26='delete-bulk';});document.querySelectorAll('[data-widget12="delete-quick"]').forEach(b=>{delete b.dataset.widget12;b.dataset.recovery26='delete-widget';});}
  new MutationObserver(bridge).observe($('#overlay'),{childList:true,subtree:true});
  const oldClose=closeOverlay;closeOverlay=function(){const was=!!$('#overlay .recovery26-manager,#overlay .recovery26-confirm'),focus=returnFocus;oldClose();if(was&&focus?.isConnected)focus.focus({preventScroll:true});};
  const oldRender=render;render=function(){oldRender();document.title='Loop · 第26阶段 · 删除与恢复';if(state.route==='settings'&&state.settingsPane==='data'){const host=$('.settings-document');if(host&&!host.querySelector('.recovery26-data-entry'))host.querySelector('h2')?.insertAdjacentHTML('afterend',`<div class="recovery26-data-entry"><div>最近删除<small>恢复任务、分组、节点与笔记</small></div>${btn('open','管理')}</div>`);}if(!filteredTasks().length&&$('.list-foot')&&!$('.list-foot [data-recovery26]'))$('.list-foot').insertAdjacentHTML('beforeend',btn('open','最近删除','text-button'));};
  window.addEventListener('click',e=>{
    const notebook=e.target.closest('[data-knowledge-action="remove-binding"],[data-knowledge-action="discard-draft"]');if(notebook){e.preventDefault();e.stopImmediatePropagation();if(notebook.dataset.knowledgeAction==='remove-binding')unlink(currentTask());else removeNote(currentTask());return;}
    const b=e.target.closest('[data-recovery26]');if(!b||b.disabled)return;e.preventDefault();e.stopImmediatePropagation();const a=b.dataset.recovery26;
    if(a==='open')manager();else if(a==='cancel'){closeOverlay();render();returnFocus?.isConnected&&returnFocus.focus();}
    else if(a==='select'||a==='owner'){active=b.dataset.id;drawList();$(`[data-recovery26="select"][data-id="${active}"]`)?.focus();}
    else if(a==='commit-delete')commit();else if(a==='delete-note')removeNote(currentTask());
    else if(a==='delete-bulk')reviewDelete([...document.querySelectorAll('[data-bulk-id][aria-checked="true"]')].map(el=>byId(el.dataset.bulkId)).filter(Boolean));
    else if(a==='delete-widget')reviewDelete([byId(b.dataset.widgetId)].filter(Boolean));
    else if(a==='restore'){const entry=archive.find(e=>e.id===active);capture();const result=restoreEntry(entry,{target:$('#recovery26-restore-target')?.value,name:$('#recovery26-group-name')?.value});if(!result.ok){$('#recovery26-restore-error').textContent=result.message;$('#recovery26-group-name')?.setAttribute('aria-invalid','true');return;}ensureSelection();render();manager();receipt(result.message);}
    else if(a==='restore-selected')showResults(restoreMany([...picked]));else if(a==='purge')purgeReview([active]);else if(a==='purge-selected')purgeReview(picked.size?[...picked]:archive.map(e=>e.id));
    else if(a==='purge-confirm'){if(!$('#recovery26-purge-agree').checked)return;for(const id of pending.ids){const i=archive.findIndex(e=>e.id===id);if(i>=0)archive.splice(i,1);picked.delete(id);}pending=null;undo=null;manager();receipt('所选示例已永久移除');}
    else if(a==='undo'){const fn=undo;undo=null;if(fn){const result=fn();if(Array.isArray(result)){if(result.some(r=>!r.ok))showResults(result);else{closeOverlay();receipt(result.length===1?result[0].message:`已恢复 ${result.length} 项`);}}else if(!$('#toast').textContent.includes('当前笔记已变更'))receipt('已撤销');}}
    else if(a==='unlink-confirm'){const d=pending,t=byId(d.ids[0]);if(!t)return;draftSession(t.id,t.notes);touchTask(t);closeOverlay();render();receipt('文件关联已解除，正文保留',[],()=>{const target=byId(t.id),k=knowledgeFor(t);if(!target||target.notes!==d.body||k.path){receipt('当前笔记已变更，请重新选择文件关联');return;}knowledgeSessions.set(t.id,clone(d.before));render();});pending=null;}
    else if(a==='clear-search'){query='';filter='all';manager();}else if(a==='review')review();
  },true);
  document.addEventListener('input',e=>{if(e.target.id==='recovery26-search'){query=e.target.value;drawList();}if(e.target.id==='recovery26-group-name'){e.target.removeAttribute('aria-invalid');$('#recovery26-restore-error').textContent='';}});
  document.addEventListener('change',e=>{if(e.target.id==='recovery26-filter'){filter=e.target.value;drawList();}if(e.target.dataset.recovery26Check){const id=e.target.dataset.recovery26Check;e.target.checked?picked.add(id):picked.delete(id);updateFooter();}if(e.target.id==='recovery26-all'){visible().forEach(item=>e.target.checked?picked.add(item.id):picked.delete(item.id));drawList();}if(e.target.name==='groupPolicy26')$('#recovery26-target-field').hidden=e.target.value==='delete';if(e.target.id==='recovery26-purge-agree')$('[data-recovery26="purge-confirm"]').disabled=!e.target.checked;});
  function review(){openDialog('第26阶段 · 删除与恢复',`<p>删除任务、速记或节点后，可立即撤销，也可从最近删除恢复。</p><p>删除分组默认保留内容；笔记移除不会删除磁盘文件。原分组、父节点或所属任务丢失时，恢复页面会说明处理方式。</p><p class="recovery26-hint">入口：任务更多菜单、设置 → 数据。初始最近删除包含独立的冲突示例，便于检阅。</p><p class="recovery26-demo-note">归档仅存于本页；刷新恢复示例。真实数据库、文件与原生窗口未接入。</p>`,btn('open','查看最近删除','button primary')+btn('cancel','返回工作台'));}
  function seeds(){const base=clone(byId(1)),record={...base,id:9261,title:'整理开发环境迁移记录',group:'旧项目资料',today:false,nodes:[node('seed26-a','核对工具链','done',[],'记录编译器版本与环境变量。')],description:'保留迁移步骤，便于新设备复用。',notes:'# 环境迁移\n\n编译器、依赖与配置的核对记录。'};add({type:'node',title:'补充验证记录',ownerId:9261,ownerTitle:record.title,parentId:null,position:1,record:node('seed26-orphan','补充验证记录','todo',[],'等待先恢复所属任务。'),group:record.group,time:'昨天 18:10'});add({type:'task',title:record.title,group:record.group,record,position:2,time:'昨天 18:10'});add({type:'note',title:'中断机制学习 · 知识笔记',ownerId:2,ownerTitle:byId(2)?.title||'中断机制学习',group:byId(2)?.group||'日常学习',body:'# 中断机制学习\n\n## 排查记录\n- 设备侧 MSI Enable\n- 驱动向量分配\n- 内核 IRQ 映射\n\n保留各层日志，逐一比较异常路径。',path:'/示例/知识库/中断机制.md',time:'今天 09:20'});add({type:'group',title:'工具与环境',group:'工具与环境',groupPosition:2,policy:'delete',sourceWas:false,members:[{record:{...clone(base),id:9262,title:'确认新环境编译参数',group:'工具与环境',today:false,nodes:[],notes:'',description:'核对编译参数与依赖。'},position:3}],time:'今天 10:05'});add({type:'node',title:'验证中断恢复路径',ownerId:1,ownerTitle:base.title,group:base.group,parentId:'missing-parent26',parentTitle:'旧验证分支',position:1,record:node('seed26-n','验证中断恢复路径','todo',[node('seed26-n1','保存恢复前后日志','done')],'切换电源状态后，检查向量和中断计数。'),time:'今天 11:12'});}
  document.addEventListener('DOMContentLoaded',()=>{seeds();$('.review-bar b').textContent='第26阶段 · 删除与恢复';$('.review-note').textContent='页面内存示例 · 刷新重置';$('.review-controls').insertAdjacentHTML('afterbegin',btn('open','最近删除','button'));reviewInfo=review;globalThis.loopWidgetReview=review;render();if(new URLSearchParams(location.search).get('view')!=='workbench')manager();});
